// דף הנחיתה של קבצים פלוס – נטען מ-index.html כשנכנסים לכתובת עם #kvatzim-plus
window.KP_SHELL = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>קבצים פלוס</title>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Secular+One&family=Assistant:wght@400;600;700;800&display=swap\">\n<style>\n:root{--night:#050816;--blue:#2f6bff;--cyan:#38d6ff;--sun:#ffc93d;--pink:#ff5fa2;--white:#f4f7ff;--soft:#a6b5dc;\n--fd:\"Secular One\",\"Assistant\",system-ui,sans-serif;--fb:\"Assistant\",system-ui,\"Segoe UI\",Arial,sans-serif;color-scheme:dark}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{margin:0;background:var(--night);color:var(--white);font-family:var(--fb);font-size:18px;line-height:1.55;overflow-x:hidden}\nbody::before{content:\"\";position:fixed;inset:-10%;z-index:-2;pointer-events:none;\n background:radial-gradient(40% 30% at 90% 5%,rgba(47,107,255,.6),transparent 70%),radial-gradient(35% 30% at 0% 50%,rgba(56,214,255,.25),transparent 70%),radial-gradient(35% 25% at 85% 100%,rgba(255,95,162,.22),transparent 70%)}\nbody::after{content:\"\";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:.12;\n background-image:linear-gradient(rgba(255,255,255,.2) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.2) 1px,transparent 1px);background-size:54px 54px}\n.wrap{max-width:1120px;margin:0 auto;padding-inline:max(16px,env(safe-area-inset-left,0px));display:grid;gap:110px;padding-block:28px 60px}\n.brand{display:flex;align-items:center;gap:14px}\n.mark{width:54px;height:54px;border-radius:16px;background:linear-gradient(145deg,var(--cyan),var(--blue));display:grid;place-items:center;box-shadow:0 0 30px rgba(47,107,255,.8)}\n.mark svg{width:32px;height:32px}\n.brand b{font-family:var(--fd);font-weight:400;font-size:30px;line-height:1}\n.brand small{display:block;color:var(--soft);font-size:15px;letter-spacing:.06em}\nh1,h2{font-family:var(--fd);font-weight:400;margin:0;line-height:1.05;text-wrap:balance}\nh1{font-size:clamp(46px,6vw,74px)}\nh2{font-size:clamp(36px,5.5vw,64px)}\n.hl{white-space:nowrap;color:var(--night);background:var(--sun);padding:0 .18em;border-radius:.12em;display:inline-block;transform:rotate(-2deg);box-shadow:0 0 50px rgba(255,201,61,.45)}\n.grad{background:linear-gradient(90deg,var(--cyan),#9db8ff 55%,var(--pink));-webkit-background-clip:text;background-clip:text;color:transparent}\n.lead{font-size:clamp(20px,2.4vw,26px);color:var(--soft);margin:0;max-width:34ch}\n.hero{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr);gap:40px;align-items:center}\n.hero .txt{display:grid;gap:26px;justify-items:start}\n.stage{perspective:1800px}\n.shot{border-radius:16px;overflow:hidden;border:2px solid rgba(143,176,255,.6);box-shadow:0 0 0 7px rgba(47,107,255,.12),0 40px 80px -20px rgba(0,0,0,.85),0 0 80px rgba(47,107,255,.45);background:#fff}\n.shot img{display:block;width:100%;height:auto}\n.hero .shot{transform:rotateY(14deg) rotateX(6deg) rotateZ(2deg);animation:float 7s ease-in-out infinite}\n@keyframes float{50%{transform:rotateY(10deg) rotateX(4deg) rotateZ(1deg) translateY(-14px)}}\n.mail{direction:ltr;display:inline-flex;align-items:center;gap:12px;font-weight:800;font-size:clamp(20px,3vw,30px);color:var(--night);background:linear-gradient(90deg,var(--sun),#ffe08a);border-radius:999px;padding:14px 30px;box-shadow:0 0 50px rgba(255,201,61,.55);border:0;cursor:pointer;font-family:var(--fb)}\n.mail:focus-visible{outline:3px solid var(--white);outline-offset:3px}\n.fee{display:inline-flex;align-items:center;gap:10px;font-size:18px;font-weight:700;background:rgba(255,95,162,.14);border:1px solid rgba(255,95,162,.55);border-radius:999px;padding:8px 18px}\n.fee b{color:var(--pink)}\n.copied{font-size:16px;color:var(--cyan);min-height:1.4em}\n.sec{display:grid;gap:34px}\n.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}\n.card{border-radius:22px;padding:26px;background:linear-gradient(160deg,rgba(255,255,255,.09),rgba(255,255,255,.03));border:1px solid rgba(255,255,255,.16);display:grid;gap:8px;align-content:start;transition:transform .25s,border-color .25s}\n.card:hover{transform:translateY(-6px);border-color:rgba(56,214,255,.6)}\n.card svg{width:40px;height:40px;stroke:var(--cyan);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 0 8px rgba(56,214,255,.7))}\n.card b{font-family:var(--fd);font-weight:400;font-size:28px;line-height:1.15}\n.card span{color:var(--soft)}\n.click{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:40px;align-items:center}\n.demo{display:grid;justify-items:center;gap:40px;position:relative}\n.bigbtn{display:inline-flex;align-items:center;gap:14px;background:#0b57d0;color:#fff;font-weight:800;font-size:44px;border-radius:999px;padding:20px 48px;box-shadow:0 0 0 12px rgba(47,107,255,.25),0 0 80px rgba(47,107,255,.9);animation:pulse 2.4s ease-in-out infinite}\n@keyframes pulse{50%{box-shadow:0 0 0 20px rgba(47,107,255,.12),0 0 110px rgba(47,107,255,1)}}\n.bigbtn svg{width:40px;height:40px}\n.toast{display:flex;align-items:center;gap:14px;background:#fff;color:#141b2d;border-radius:18px;padding:18px 24px;font-size:24px;font-weight:700;box-shadow:0 30px 60px -10px rgba(0,0,0,.7)}\n.toast .ok{width:44px;height:44px;border-radius:50%;background:#1e9e5a;display:grid;place-items:center;flex:none}\n.toast small{display:block;font-size:17px;font-weight:600;color:#5d667a}\n.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}\n.gallery figure{margin:0;display:grid;gap:10px}\n.gallery figcaption{color:var(--soft);font-size:17px}\n.gallery figcaption b{color:var(--white)}\n.price{border-radius:30px;padding:clamp(28px,5vw,60px);background:linear-gradient(150deg,rgba(47,107,255,.35),rgba(255,95,162,.18));border:1px solid rgba(255,255,255,.2);display:grid;gap:22px;justify-items:start}\n.price .tag{font-weight:800;color:var(--pink);letter-spacing:.04em;font-size:20px}\n.price ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 26px;width:100%}\n.price li{display:flex;align-items:center;gap:10px;font-weight:700;font-size:20px}\n.price li::before{content:\"✓\";display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:rgba(56,214,255,.18);color:var(--cyan);flex:none}\n.foot{text-align:center;color:var(--soft);font-size:15px}\n@media (max-width:820px){\n  .hero,.click{grid-template-columns:minmax(0,1fr)}\n  .grid,.gallery,.price ul{grid-template-columns:minmax(0,1fr)}\n  .wrap{gap:80px}\n  .bigbtn{font-size:34px}\n}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n</style></head><body>\n<div class=\"wrap\">\n  <header class=\"brand\"><div class=\"mark\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M5 20V10a7 7 0 0 1 14 0v10\"/><path d=\"M9 20v-9a3 3 0 0 1 6 0v9\"/></svg></div><div><b>קבצים פלוס</b><small>DriveGate · תוסף לכרום</small></div></header>\n\n  <section class=\"hero\">\n    <div class=\"txt\">\n      <h1>כל הדרייב.<br><span class=\"hl\">בלחיצה אחת.</span></h1>\n      <p class=\"lead\">כל התיקיות המשותפות במקום אחד, ועותק אישי <span class=\"grad\">שמשותף איתך תוך שניות</span>.</p>\n      <button class=\"mail\" type=\"button\" data-copy>menaka05567@gmail.com</button>\n      <span class=\"copied\" aria-live=\"polite\"></span>\n      <span class=\"fee\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"#ff5fa2\"><path d=\"M6 3h12l4 6-10 12L2 9z\"/></svg><b>בתשלום סמלי</b> לכיסוי עלויות פיתוח ותחזוקה</span>\n    </div>\n    <div class=\"stage\"><div class=\"shot\"><img src=\"data:image/webp;base64,\" alt=\"דף הבית של קבצים פלוס\" width=\"1910\" height=\"748\"></div></div>\n  </section>\n\n  <section class=\"click\">\n    <div class=\"sec\">\n      <h2>לוחצים.<br><span class=\"grad\">וזה אצלך.</span></h2>\n      <p class=\"lead\">בוחרים קובץ, לוחצים \"עותק\", והעותק נשמר ב\"העותקים שלי\" ומשותף איתך מיד. גם קבצים של כמה ג׳יגה.</p>\n    </div>\n    <div class=\"demo\">\n      <div class=\"bigbtn\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\"/></svg>עותק</div>\n      <div class=\"toast\"><div class=\"ok\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"><path d=\"M5 12l5 5L20 7\"/></svg></div><div>העותק מוכן!<small>משותף איתך · מחכה ב\"העותקים שלי\"</small></div></div>\n    </div>\n  </section>\n\n  <section class=\"sec\">\n    <h2>מה <span class=\"grad\">בפנים?</span></h2>\n    <div class=\"grid\">\n      <div class=\"card\"><svg viewBox=\"0 0 24 24\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\"/></svg><b>עותק בלחיצה</b><span>עותק אישי שמשותף איתך תוך שניות.</span></div>\n      <div class=\"card\"><svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-3.5-3.5\"/></svg><b>חיפוש חכם</b><span>מילה אחת, בכל האחסונים בבת אחת.</span></div>\n      <div class=\"card\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9\"/><path d=\"M10 21h4\"/></svg><b>חדש בדרייב</b><span>כל מה שעלה השבוע, מסודר לפי אחסון.</span></div>\n      <div class=\"card\"><svg viewBox=\"0 0 24 24\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg><b>צ׳אט והודעות</b><span>עדכונים, ערוצי נושא, סקרים והודעות פרטיות.</span></div>\n      <div class=\"card\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 6h15l-1.5 9h-12z\"/><path d=\"M6 6 5 3H2\"/><circle cx=\"9\" cy=\"20\" r=\"1.4\"/><circle cx=\"18\" cy=\"20\" r=\"1.4\"/></svg><b>סל הורדות</b><span>אוספים מכמה תיקיות, ועותק לכולם בבת אחת.</span></div>\n      <div class=\"card\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 6h13M3 12h9M3 18h9\"/><path d=\"M18 14v8M14 18h8\"/></svg><b>רשימות ומעקב</b><span>שומרים לרשימות ומקבלים סימון כשתיקייה מתעדכנת.</span></div>\n    </div>\n  </section>\n\n  <section class=\"sec\">\n    <h2>ככה זה <span class=\"grad\">נראה</span></h2>\n    <div class=\"gallery\">\n      <figure><div class=\"shot\"><img src=\"data:image/webp;base64,\" alt=\"מסך האחסונים\" loading=\"lazy\"></div><figcaption><b>אחסונים.</b> כל האחסונים המשותפים, מסודרים.</figcaption></figure>\n      <figure><div class=\"shot\"><img src=\"data:image/webp;base64,\" alt=\"תיקייה עם קבצים\" loading=\"lazy\"></div><figcaption><b>תיקייה.</b> גודל, תאריך ומשך ליד כל קובץ.</figcaption></figure>\n      <figure><div class=\"shot\"><img src=\"data:image/webp;base64,\" alt=\"חדש היום בדרייב\" loading=\"lazy\"></div><figcaption><b>חדש היום.</b> כפתור עותק ליד כל קובץ.</figcaption></figure>\n      <figure><div class=\"shot\"><img src=\"data:image/webp;base64,\" alt=\"תצוגת רשת של תיקיות\" loading=\"lazy\"></div><figcaption><b>רשת או רשימה.</b> מיון לפי חדש, שם או גודל.</figcaption></figure>\n    </div>\n  </section>\n\n  <section class=\"price\">\n    <span class=\"tag\">כמה זה עולה?</span>\n    <h2><span class=\"hl\">תשלום סמלי.</span></h2>\n    <p class=\"lead\">רק כדי לכסות את עלויות הפיתוח והתחזוקה, ושהכל ימשיך לעבוד חלק.</p>\n    <ul><li>כל האחסונים</li><li>עותק בלחיצה</li><li>עדכוני גרסה</li><li>צ׳אט והודעות</li><li>חדש בדרייב</li><li>תמיכה אישית</li></ul>\n    <button class=\"mail\" type=\"button\" data-copy>menaka05567@gmail.com</button>\n    <span class=\"copied\" aria-live=\"polite\"></span>\n  </section>\n\n  <p class=\"foot\">קבצים פלוס · DriveGate · לחצו על המייל כדי להעתיק אותו</p>\n</div>\n<script>\ndocument.querySelectorAll('[data-copy]').forEach(function (b) {\n  b.addEventListener('click', function () {\n    var note = b.nextElementSibling, t = b.textContent.trim();\n    var done = function () { note.textContent = 'המייל הועתק ✓'; };\n    try { navigator.clipboard.writeText(t).then(done, function () { note.textContent = t; }); } catch (e) { note.textContent = t; }\n  });\n});\n</script>\n<script>addEventListener(\"hashchange\",function(){if(location.hash!==\"#kvatzim-plus\")location.reload()});</script>\n</body></html>\n";
